Here is the commit message:
mmc: sdio: Allow sdio operations in other threads during
 sdio_add_func()

This fixes a bug introduced by 807e8e40673d ("mmc: Fix sd/sdio/mmc
initialization frequency retries") that prevented SDIO drivers from
performing SDIO commands in their probe routines -- the above patch
called mmc_claim_host() before sdio_add_func(), which causes a deadlock
if an external SDIO driver calls sdio_claim_host().

Fix tested on an OLPC XO-1.75 with libertas on SDIO.

Signed-off-by: Dmitry Shmidt <dimitrysh@google.com>
Reviewed-and-Tested-by: Chris Ball <cjb@laptop.org>
Signed-off-by: Chris Ball <cjb@laptop.org>

Here is the root cause:
The bug was caused by the premature call to `mmc_claim_host(host);` before the `sdio_add_func()` operation, which led to a deadlock situation when an external SDIO driver attempted to call `sdio_claim_host()`. This improper ordering of operations prevented SDIO drivers from executing commands during their probe routines, as the host was already claimed, blocking further access.

Here is the patch:
  */
 int mmc_attach_sdio(struct mmc_host *host)
 {
 	int err, i, funcs;
 	u32 ocr;
 	struct mmc_card *card;

 	BUG_ON(!host);
 	WARN_ON(!host->claimed);

 	err = mmc_send_io_op_cond(host, 0, &ocr);
 	if (err)
 		return err;

 	mmc_attach_bus(host, &mmc_sdio_ops);
 	if (host->ocr_avail_sdio)
 		host->ocr_avail = host->ocr_avail_sdio;

 	/*
 	 * Sanity check the voltages that the card claims to
 	 * support.
 	 */
 	if (ocr & 0x7F) {
 		printk(KERN_WARNING "%s: card claims to support voltages "
 		       "below the defined range. These will be ignored.\n",
 		       mmc_hostname(host));
 		ocr &= ~0x7F;
 	}

 	host->ocr = mmc_select_voltage(host, ocr);

 	/*
 	 * Can we support the voltage(s) of the card(s)?
 	 */
 	if (!host->ocr) {
 		err = -EINVAL;
 		goto err;
 	}

 	/*
 	 * Detect and init the card.
 	 */
 	err = mmc_sdio_init_card(host, host->ocr, NULL, 0);
 	if (err)
 		goto err;
 	card = host->card;

 	/*
 	 * Enable runtime PM only if supported by host+card+board
 	 */
 	if (host->caps & MMC_CAP_POWER_OFF_CARD) {
 		/*
 		 * Let runtime PM core know our card is active
 		 */
 		err = pm_runtime_set_active(&card->dev);
 		if (err)
 			goto remove;

 		/*
 		 * Enable runtime PM for this card
 		 */
 		pm_runtime_enable(&card->dev);
 	}

 	/*
 	 * The number of functions on the card is encoded inside
 	 * the ocr.
 	 */
 	funcs = (ocr & 0x70000000) >> 28;
 	card->sdio_funcs = 0;

 	/*
 	 * Initialize (but don't add) all present functions.
 	 */
 	for (i = 0; i < funcs; i++, card->sdio_funcs++) {
 		err = sdio_init_func(host->card, i + 1);
 		if (err)
 			goto remove;

 		/*
 		 * Enable Runtime PM for this func (if supported)
 		 */
 		if (host->caps & MMC_CAP_POWER_OFF_CARD)
 			pm_runtime_enable(&card->sdio_func[i]->dev);
 	}

 	/*
 	 * First add the card to the driver model...
 	 */
 	mmc_release_host(host);
 	err = mmc_add_card(host->card);
-	mmc_claim_host(host);
 	if (err)
 		goto remove_added;

 	/*
 	 * ...then the SDIO functions.
 	 */
 	for (i = 0;i < funcs;i++) {
 		err = sdio_add_func(host->card->sdio_func[i]);
 		if (err)
 			goto remove_added;
 	}

+	mmc_claim_host(host);
 	return 0;


 remove_added:
 	/* Remove without lock if the device has been added. */
-	mmc_release_host(host);
 	mmc_sdio_remove(host);
 	mmc_claim_host(host);
 remove:
 	/* And with lock if it hasn't been added. */
 	mmc_release_host(host);
 	if (host->card)
 		mmc_sdio_remove(host);
 	mmc_claim_host(host);
 err:
 	mmc_detach_bus(host);

 	printk(KERN_ERR "%s: error %d whilst initialising SDIO card\n",
 		mmc_hostname(host), err);

 	return err;
 }



